package com.hmdp.ai.infrastructure.mcp;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.hmdp.ai.domain.mcp.*;import com.hmdp.ai.infrastructure.external.*;import com.hmdp.ai.infrastructure.model.SecretResolutionService;import java.net.URI;import java.time.Duration;import java.util.*;
public final class McpHttpClient {private final SafeHttpClient http;private final SecretResolutionService secrets;private final ObjectMapper mapper;McpHttpClient(SafeHttpClient http,SecretResolutionService secrets,ObjectMapper mapper){this.http=http;this.secrets=secrets;this.mapper=mapper;}public JsonNode initialize(McpServer s){ObjectNode p=mapper.createObjectNode().put("protocolVersion","2025-03-26");p.set("capabilities",mapper.createObjectNode());p.set("clientInfo",mapper.createObjectNode().put("name","hmdp-agent-platform").put("version","1"));return call(s,"initialize",p);}public List<McpToolDescriptor>tools(McpServer s){JsonNode result=call(s,"tools/list",mapper.createObjectNode());List<McpToolDescriptor>tools=new ArrayList<>();for(JsonNode n:result.path("tools"))tools.add(new McpToolDescriptor(n.path("name").asText(),n.path("description").asText(""),n.has("inputSchema")?n.get("inputSchema"):mapper.createObjectNode()));return tools;}public JsonNode execute(McpServer s,String tool,JsonNode arguments){ObjectNode p=mapper.createObjectNode().put("name",tool);p.set("arguments",arguments);return call(s,"tools/call",p);}
    private JsonNode call(McpServer s,String method,JsonNode params){try{ObjectNode body=mapper.createObjectNode().put("jsonrpc","2.0").put("id",UUID.randomUUID().toString()).put("method",method);body.set("params",params);Map<String,String>headers=new LinkedHashMap<>();headers.put("Content-Type","application/json");headers.put("Accept","application/json, text/event-stream");if(s.getSecretRef()!=null&&!s.getSecretRef().isEmpty())headers.put("Authorization","Bearer "+secrets.resolve(s.getSecretRef()));OutboundHttpResponse response=http.execute(new OutboundHttpRequest(URI.create(s.getEndpoint()),"POST",headers,mapper.writeValueAsBytes(body),Duration.ofMillis(s.getTimeoutMs()),2*1024*1024,new LinkedHashSet<>(Arrays.asList("application/json","text/event-stream")),s.isAllowPrivateNetwork()));if(response.getStatusCode()<200||response.getStatusCode()>=300)throw new IllegalStateException("MCP_STATUS_"+response.getStatusCode());JsonNode envelope=response.getContentType().equals("text/event-stream")?sse(response.bodyAsUtf8()):mapper.readTree(response.getBody());if(envelope.has("error"))throw new IllegalStateException("MCP_REMOTE_ERROR");return envelope.path("result");}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalStateException("MCP_CALL_FAILED",e);}}
    private JsonNode sse(String value)throws Exception{JsonNode last=NullNode.instance;for(String line:value.split("\\R"))if(line.startsWith("data:"))last=mapper.readTree(line.substring(5).trim());if(last.isNull())throw new IllegalArgumentException("MCP_RESPONSE_INVALID");return last;}}
